using System;using System.IO;using System.Linq;using System.Collections.Generic;using System.Runtime.InteropServices;using System.Windows.Media.Imaging;
namespace DesktopBox {
// Compatibility adapter for the locally verified NVIDIA driver. Registry data is
// only artwork/candidate metadata: Explorer must independently confirm a live icon.
public static class TrayRecovery {
 [StructLayout(LayoutKind.Sequential)]struct Identifier {public uint Size;public IntPtr Window;public uint Id;public Guid Guid;}
 [StructLayout(LayoutKind.Sequential)]struct Rect{public int Left,Top,Right,Bottom;}
 delegate bool EnumProc(IntPtr window,IntPtr parameter);
 [DllImport("shell32.dll")]static extern int Shell_NotifyIconGetRect(ref Identifier id,out Rect rect);
 [DllImport("user32.dll")]static extern bool EnumWindows(EnumProc callback,IntPtr parameter);
 [DllImport("user32.dll",CharSet=CharSet.Unicode)]static extern IntPtr FindWindowEx(IntPtr parent,IntPtr after,string cls,string title);
 [DllImport("user32.dll")]static extern uint GetWindowThreadProcessId(IntPtr window,out uint pid);
 static readonly Guid PowerGuid=new Guid("7820ae75-23e3-4229-82c1-e41cb67d5b9c");
 static string checkedFile="",checkedHash="";static DateTime checkedTime;
 public static bool DuplicatePower(TrayMirror.IconItem item){return item.Guid==PowerGuid&&String.Equals(Path.GetFileName(item.Executable),"explorer.exe",StringComparison.OrdinalIgnoreCase);}
 public static bool Live(TrayMirror.IconItem item){var id=new Identifier{Size=(uint)Marshal.SizeOf(typeof(Identifier)),Window=item.Window,Id=item.Id,Guid=item.Guid};Rect rect;return Shell_NotifyIconGetRect(ref id,out rect)==0;}
 static bool VerifiedDriver(string exe){try{string file=Path.GetFullPath(Path.Combine(Path.GetDirectoryName(exe),"..","nvui.dll"));DateTime time=File.GetLastWriteTimeUtc(file);if(file!=checkedFile||time!=checkedTime){checkedFile=file;checkedTime=time;checkedHash="";using(var sha=System.Security.Cryptography.SHA256.Create())using(var stream=File.OpenRead(file))checkedHash=BitConverter.ToString(sha.ComputeHash(stream)).Replace("-","");}return checkedHash=="7D1A78A79D443B83F4E632A7F7C040BEB7F345F4FD574E11A130486DB4823490";}catch{return false;}}
 public static List<TrayMirror.IconItem> Read(){var result=new List<TrayMirror.IconItem>();try{using(var root=Microsoft.Win32.Registry.CurrentUser.OpenSubKey(@"Control Panel\NotifyIconSettings")){if(root==null)return result;foreach(string name in root.GetSubKeyNames())using(var key=root.OpenSubKey(name)){if(key==null||Convert.ToUInt32(key.GetValue("UID",0))!=1051)continue;string path=TrayMirror.ExpandPath(key.GetValue("ExecutablePath","").ToString());if(!String.Equals(Path.GetFileName(path),"NVDisplay.Container.exe",StringComparison.OrdinalIgnoreCase)||!VerifiedDriver(path))continue;var processes=new HashSet<uint>();int session=System.Diagnostics.Process.GetCurrentProcess().SessionId;foreach(var process in System.Diagnostics.Process.GetProcessesByName("NVDisplay.Container"))using(process){if(process.SessionId==session)processes.Add((uint)process.Id);}if(processes.Count==0)continue;var windows=new List<IntPtr>();EnumWindows((h,p)=>{uint pid;GetWindowThreadProcessId(h,out pid);if(processes.Contains(pid))windows.Add(h);return true;},IntPtr.Zero);IntPtr message=IntPtr.Zero;while((message=FindWindowEx(new IntPtr(-3),message,null,null))!=IntPtr.Zero){uint pid;GetWindowThreadProcessId(message,out pid);if(processes.Contains(pid))windows.Add(message);}foreach(var window in windows){uint pid;GetWindowThreadProcessId(window,out pid);var item=new TrayMirror.IconItem{Key="w:"+window.ToInt64()+"|1051",Window=window,Id=1051,ProcessId=pid,Executable=path,Tip=key.GetValue("InitialTooltip","NVIDIA 设置").ToString(),Callback=0xb00,Version=3,VersionConfirmed=true,Recovered=true};if(!Live(item))continue;var png=key.GetValue("IconSnapshot") as byte[];if(png==null||png.Length==0||png.Length>1024*1024)continue;using(var stream=new MemoryStream(png)){var image=new BitmapImage();image.BeginInit();image.CacheOption=BitmapCacheOption.OnLoad;image.StreamSource=stream;image.EndInit();image.Freeze();item.Image=image;}result.Add(item);break;}}}}catch{}return result;}
}
}
